empty<-structure(list(),names=character());target<-list(event='default',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing');ctx<-build_calculation_context('2024-01-01','2024-01-01',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing',currency='EUR')$value
